-- ACCREDITATION V3: safe, repeatable installation
-- Preserves existing V3 data; re-running resets no progress and deletes no evidence.
create extension if not exists pgcrypto;

create table if not exists public.accreditation_v3_profiles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  full_name text not null,
  job_title text,
  role text not null check (role in ('department_head','quality_office','director')),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.accreditation_v3_projects (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  name_ru text not null,
  name_uz text not null,
  name_en text not null,
  kind text not null check (kind in ('complex','special')),
  created_at timestamptz not null default now()
);

create table if not exists public.accreditation_v3_indicators (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.accreditation_v3_projects(id) on delete cascade,
  code text not null,
  responsible_label text,
  responsible_user_id uuid references auth.users(id) on delete set null,
  status text not null default 'draft' check (status in ('draft','in_progress','review','revision','approved')),
  completion_percent integer not null default 0 check (completion_percent between 0 and 100),
  submitted_at timestamptz,
  approved_at timestamptz,
  updated_at timestamptz not null default now(),
  unique(project_id,code)
);

create table if not exists public.accreditation_v3_documents (
  id uuid primary key default gen_random_uuid(),
  indicator_id uuid not null references public.accreditation_v3_indicators(id) on delete cascade,
  uploaded_by uuid not null references auth.users(id),
  file_name text not null,
  storage_path text not null,
  version integer not null default 1,
  status text not null default 'in_progress',
  created_at timestamptz not null default now()
);

create table if not exists public.accreditation_v3_reviews (
  id uuid primary key default gen_random_uuid(),
  indicator_id uuid not null references public.accreditation_v3_indicators(id) on delete cascade,
  reviewer_id uuid not null references auth.users(id),
  decision text not null check (decision in ('approved','revision')),
  comment text not null,
  created_at timestamptz not null default now()
);

create table if not exists public.accreditation_v3_history (
  id bigint generated always as identity primary key,
  indicator_id uuid not null references public.accreditation_v3_indicators(id) on delete cascade,
  actor_id uuid references auth.users(id),
  old_status text,
  new_status text,
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

on conflict(code) do update set name_ru=excluded.name_ru,name_uz=excluded.name_uz,name_en=excluded.name_en,kind=excluded.kind;

on conflict(project_id,code) do update set responsible_label=excluded.responsible_label;

create or replace view public.accreditation_v3_project_progress as
select p.code project_code,p.name_ru,p.name_uz,p.name_en,
 count(i.id)::int total,
 count(i.id) filter(where i.status='approved')::int approved,
 count(i.id) filter(where i.status='review')::int review,
 count(i.id) filter(where i.status='revision')::int revision,
 count(i.id) filter(where i.status='in_progress')::int in_progress,
 count(i.id) filter(where i.status='draft')::int draft,
 coalesce(round(avg(i.completion_percent)),0)::int progress
from public.accreditation_v3_projects p
left join public.accreditation_v3_indicators i on i.project_id=p.id
group by p.id,p.code,p.name_ru,p.name_uz,p.name_en;

create or replace function public.accreditation_v3_is_reviewer()
returns boolean language sql stable security definer set search_path=public as $$
 select coalesce((auth.jwt()->'app_metadata'->>'role')='admin',false)
 or exists(select 1 from public.accreditation_v3_profiles p where p.user_id=auth.uid() and p.is_active and p.role='quality_office');
$$;

create or replace function public.accreditation_v3_is_director()
returns boolean language sql stable security definer set search_path=public as $$
 select exists(select 1 from public.accreditation_v3_profiles p where p.user_id=auth.uid() and p.is_active and p.role='director');
$$;

alter table public.accreditation_v3_profiles enable row level security;
alter table public.accreditation_v3_projects enable row level security;
alter table public.accreditation_v3_indicators enable row level security;
alter table public.accreditation_v3_documents enable row level security;
alter table public.accreditation_v3_reviews enable row level security;
alter table public.accreditation_v3_history enable row level security;

do $$
declare r record;
begin
 for r in select policyname,tablename from pg_policies where schemaname='public' and tablename like 'accreditation_v3_%'
 loop execute format('drop policy if exists %I on public.%I',r.policyname,r.tablename); end loop;
end $$;

create policy "v3 public projects" on public.accreditation_v3_projects for select to anon,authenticated using(true);
create policy "v3 public indicator progress" on public.accreditation_v3_indicators for select to anon,authenticated using(true);
create policy "v3 own profile" on public.accreditation_v3_profiles for select to authenticated
 using(user_id=auth.uid() or public.accreditation_v3_is_reviewer() or public.accreditation_v3_is_director());
create policy "v3 department update own indicators" on public.accreditation_v3_indicators for update to authenticated
 using(responsible_user_id=auth.uid() or public.accreditation_v3_is_reviewer())
 with check(responsible_user_id=auth.uid() or public.accreditation_v3_is_reviewer());
create policy "v3 documents read permitted" on public.accreditation_v3_documents for select to authenticated
 using(uploaded_by=auth.uid() or public.accreditation_v3_is_reviewer() or public.accreditation_v3_is_director());
create policy "v3 documents upload own" on public.accreditation_v3_documents for insert to authenticated
 with check(uploaded_by=auth.uid() and exists(select 1 from public.accreditation_v3_indicators i where i.id=indicator_id and i.responsible_user_id=auth.uid()));
create policy "v3 reviews read" on public.accreditation_v3_reviews for select to authenticated
 using(public.accreditation_v3_is_reviewer() or public.accreditation_v3_is_director() or exists(select 1 from public.accreditation_v3_indicators i where i.id=indicator_id and i.responsible_user_id=auth.uid()));
create policy "v3 reviewer creates review" on public.accreditation_v3_reviews for insert to authenticated
 with check(public.accreditation_v3_is_reviewer() and reviewer_id=auth.uid());
create policy "v3 history read" on public.accreditation_v3_history for select to authenticated
 using(public.accreditation_v3_is_reviewer() or public.accreditation_v3_is_director() or exists(select 1 from public.accreditation_v3_indicators i where i.id=indicator_id and i.responsible_user_id=auth.uid()));

grant select on public.accreditation_v3_project_progress to anon,authenticated;

create or replace view public.accreditation_v3_responsible_progress as
select i.responsible_label,
 count(*)::int total,
 count(*) filter(where i.status='approved')::int approved,
 count(*) filter(where i.status='review')::int review,
 count(*) filter(where i.status='revision')::int revision,
 count(*) filter(where i.status='in_progress')::int in_progress,
 count(*) filter(where i.status='draft')::int draft,
 coalesce(round(avg(i.completion_percent)),0)::int progress
from public.accreditation_v3_indicators i
where coalesce(i.responsible_label,'') <> ''
group by i.responsible_label;

grant select on public.accreditation_v3_responsible_progress to authenticated;


values('accreditation-v3-evidence','accreditation-v3-evidence',false,52428800)
on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit;

drop policy if exists "v3 evidence upload" on storage.objects;
drop policy if exists "v3 evidence read" on storage.objects;
create policy "v3 evidence upload" on storage.objects for insert to authenticated
 with check(bucket_id='accreditation-v3-evidence');
create policy "v3 evidence read" on storage.objects for select to authenticated
 using(bucket_id='accreditation-v3-evidence');

create or replace function public.accreditation_v3_log_status()
returns trigger language plpgsql security definer set search_path=public as $$
begin
 if old.status is distinct from new.status then
   values(new.id,auth.uid(),old.status,new.status,jsonb_build_object('completion_percent',new.completion_percent));
 end if;
 new.updated_at=now();
 return new;
end $$;
drop trigger if exists accreditation_v3_status_trigger on public.accreditation_v3_indicators;
create trigger accreditation_v3_status_trigger before update on public.accreditation_v3_indicators
for each row execute function public.accreditation_v3_log_status();

select 'ACCREDITATION V3 INSTALLED' result,
 (select count(*) from public.accreditation_v3_indicators) total_indicators,
 (select count(*) from public.accreditation_v3_projects) projects;
